mapper.select:
select b.batch_no from dy_rpa_outreach_batch b inner join dy_rpa_shop_config sc on sc.shop_config_id = b.shop_config_id where b.worker_id = #{workerId} and b.status = 'leased' and b.lease_expire_time > sysdate()
and sc.shop_code = #{preferredShopCode}
order by b.batch_id desc limit 1

select sc.shop_config_id as shopConfigId, sc.shop_code as shopCode, sc.shop_name as shopName, sc.douyin_account_code as douyinAccountCode, sc.douyin_shop_name as douyinShopName, sc.message_template as messageTemplate, sc.message_templates_json as messageTemplatesJson, sc.daily_limit as dailyLimit, sc.hourly_limit as hourlyLimit, sc.burst_size as burstSize, sc.rest_minutes as restMinutes, sc.allowed_start_time as allowedStartTime, sc.allowed_end_time as allowedEndTime, sc.refund_cooldown_days as refundCooldownDays, sc.cancelled_cooldown_days as cancelledCooldownDays, sc.pause_on_captcha as pauseOnCaptcha, sc.max_consecutive_failures as maxConsecutiveFailures, ( select count(1) from dy_rpa_outreach_task done where done.shop_config_id = sc.shop_config_id and done.completed_time >= curdate() and done.status in ('ordered', 'contacted') ) as dailyCompleted, sc.daily_limit - ( select count(1) from dy_rpa_outreach_task done where done.shop_config_id = sc.shop_config_id and done.completed_time >= curdate() and done.status in ('ordered', 'contacted') ) as dailyRemaining from dy_rpa_outreach_task t inner join dy_rpa_shop_config sc on sc.shop_config_id = t.shop_config_id and sc.status = '0' where t.status = 'pending' and t.attempt_count < t.max_attempts and time_format(curtime(), '%H:%i') between sc.allowed_start_time and sc.allowed_end_time
and sc.shop_code = #{preferredShopCode}
and not exists ( select 1 from dy_rpa_outreach_batch b where b.shop_config_id = sc.shop_config_id and b.status = 'leased' ) and ( select count(1) from dy_rpa_outreach_task done where done.shop_config_id = sc.shop_config_id and done.completed_time >= curdate() and done.status in ('ordered', 'contacted') ) < sc.daily_limit and ( select count(1) from dy_rpa_outreach_task hour_done where hour_done.shop_config_id = sc.shop_config_id and hour_done.completed_time >= date_sub(sysdate(), interval 1 hour) and hour_done.status in ('ordered', 'contacted', 'suppressed', 'skipped') ) < sc.hourly_limit order by t.priority desc, t.task_id asc limit 1

mapper.update:
update dy_rpa_outreach_task set status = 'leased', batch_no = #{batchNo}, lease_token = #{leaseToken}, worker_id = #{workerId}, lease_expire_time = date_add(sysdate(), interval #{leaseMinutes} minute), attempt_count = attempt_count + 1, first_claim_time = ifnull(first_claim_time, sysdate()), update_time = sysdate() where task_id in
#{taskId}
and status = 'pending'

update dy_rpa_outreach_batch
set task_count = #{taskCount}, update_time = sysdate()
where batch_no = #{batchNo}

update dy_rpa_outreach_batch
set lease_expire_time = date_add(sysdate(), interval #{leaseMinutes} minute),
    update_time = sysdate()
where batch_no = #{batchNo}
  and lease_token = #{leaseToken}
  and worker_id = #{workerId}
  and status = 'leased'
  and lease_expire_time > sysdate()

update dy_rpa_outreach_task
set lease_expire_time = date_add(sysdate(), interval #{leaseMinutes} minute),
    update_time = sysdate()
where batch_no = #{batchNo}
  and lease_token = #{leaseToken}
  and worker_id = #{workerId}
  and status = 'leased'

update dy_rpa_outreach_batch
set status = 'released', active_shop_key = null, completed_time = sysdate(), update_time = sysdate()
where batch_no = #{batchNo}
  and lease_token = #{leaseToken}
  and worker_id = #{workerId}
  and status = 'leased'

