mapper.select:
select bl.blacklist_id as blacklistId, bl.viewer_id as viewerId, bl.scope_key as scopeKey, bl.shop_config_id as shopConfigId, bl.reason, bl.remark, bl.operator_id as operatorId, bl.operator_name as operatorName, bl.create_time as createTime, bl.update_time as updateTime, v.nickname, v.sec_uid as secUid, case when bl.scope_key = 'GLOBAL' then '所有店铺' else sc.shop_name end as scopeName, sc.shop_code as shopCode, sc.shop_name as shopName from dy_rpa_viewer_blacklist bl inner join dy_viewer v on v.viewer_id = bl.viewer_id left join dy_rpa_shop_config sc on sc.shop_config_id = bl.shop_config_id where 1 = 1 and bl.shop_config_id = #{shopConfigId}
and (v.nickname like concat('%', #{keyword}, '%') or v.sec_uid like concat('%', #{keyword}, '%'))
and bl.reason = #{reason} order by bl.blacklist_id desc

